#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int R, C;
    cin >> R >> C;

    vector<string> grid(R);
    for (int i = 0; i < R; i++) {
        cin >> grid[i];
    }

    int T;
    cin >> T;
    vector<pair<int,int>> tasks(T);
    for (int i = 0; i < T; i++) {
        cin >> tasks[i].first >> tasks[i].second;
    }

    // Convert grid to graph and find all room positions
    vector<vector<int>> room_id(R, vector<int>(C, -1));
    vector<pair<int,int>> room_pos;
    int n = 0;

    for (int i = 0; i < R; i++) {
        for (int j = 0; j < C; j++) {
            if (grid[i][j] == '.') {
                room_id[i][j] = n++;
                room_pos.push_back({i, j});
            }
        }
    }

    // Build tree using BFS/DFS
    vector<vector<int>> adj(n);
    vector<vector<int>> edge_count(n, vector<int>(n, 0));
    vector<bool> visited(n, false);
    queue<int> q;

    // Find first room to start BFS
    int start = -1;
    for (int i = 0; i < n && start == -1; i++) {
        if (grid[room_pos[i].first][room_pos[i].second] == '.') {
            start = i;
        }
    }

    if (start != -1) {
        q.push(start);
        visited[start] = true;

        int dr[] = {-1, 1, 0, 0};
        int dc[] = {0, 0, -1, 1};

        while (!q.empty()) {
            int u = q.front();
            q.pop();

            int r = room_pos[u].first;
            int c = room_pos[u].second;

            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];

                if (nr >= 0 && nr < R && nc >= 0 && nc < C && grid[nr][nc] == '.') {
                    int v = room_id[nr][nc];
                    if (!visited[v]) {
                        visited[v] = true;
                        adj[u].push_back(v);
                        adj[v].push_back(u);
                        q.push(v);
                    }
                }
            }
        }
    }

    // For each consecutive pair of tasks, find path and count edge usage
    vector<vector<int>> edge_usage(n, vector<int>(n, 0));

    auto get_path = [&](int start, int end) -> vector<int> {
        vector<int> parent(n, -1);
        vector<bool> vis(n, false);
        queue<int> q;

        q.push(start);
        vis[start] = true;

        while (!q.empty()) {
            int u = q.front();
            q.pop();

            if (u == end) break;

            for (int v : adj[u]) {
                if (!vis[v]) {
                    vis[v] = true;
                    parent[v] = u;
                    q.push(v);
                }
            }
        }

        vector<int> path;
        int curr = end;
        while (curr != -1) {
            path.push_back(curr);
            curr = parent[curr];
        }
        reverse(path.begin(), path.end());
        return path;
    };

    // Start from first task
    int current = tasks[0].first * C + tasks[0].second;
    // Convert to room_id
    for (int i = 0; i < n; i++) {
        if (room_pos[i].first == tasks[0].first && room_pos[i].second == tasks[0].second) {
            current = i;
            break;
        }
    }

    for (int t = 1; t < T; t++) {
        int target_r = tasks[t].first;
        int target_c = tasks[t].second;
        int target = -1;

        for (int i = 0; i < n; i++) {
            if (room_pos[i].first == target_r && room_pos[i].second == target_c) {
                target = i;
                break;
            }
        }

        if (target == -1) continue;

        vector<int> path = get_path(current, target);

        // Count edge usage
        for (int i = 0; i < (int)path.size() - 1; i++) {
            int u = path[i], v = path[i+1];
            edge_usage[u][v]++;
            edge_usage[v][u]++;
        }

        current = target;
    }

    // Calculate total cost
    // For each edge that is used, we need to consider:
    // - The light is on while traversing (1 unit per traversal)
    // - The light may need to be turned on/off
    // Since each traversal takes 1 unit time and we need lights on during traversal,
    // total cost = sum of traversal times + switching costs

    long long total_cost = 0;

    // Count total traversals
    for (int u = 0; u < n; u++) {
        for (int v = u + 1; v < n; v++) {
            if (edge_usage[u][v] > 0) {
                // Each traversal takes 1 time unit
                total_cost += edge_usage[u][v];
            }
        }
    }

    // Add switching costs
    // For each room, count how many times we enter it (excluding start)
    // Each entry requires turning on the light
    vector<int> entry_count(n, 0);
    current = -1;
    for (int i = 0; i < n; i++) {
        if (room_pos[i].first == tasks[0].first && room_pos[i].second == tasks[0].second) {
            current = i;
            break;
        }
    }

    for (int t = 1; t < T; t++) {
        int target_r = tasks[t].first;
        int target_c = tasks[t].second;
        int target = -1;

        for (int i = 0; i < n; i++) {
            if (room_pos[i].first == target_r && room_pos[i].second == target_c) {
                target = i;
                break;
            }
        }

        if (target == -1) continue;

        vector<int> path = get_path(current, target);

        // Count entries for rooms along path (except start)
        for (int i = 1; i < (int)path.size(); i++) {
            entry_count[path[i]]++;
        }

        current = target;
    }

    // Add 1 for turning on each time we enter a room
    for (int i = 0; i < n; i++) {
        total_cost += entry_count[i];
    }

    // Add 1 for turning off lights at the end (for rooms that have lights on)
    // Actually, we need to turn off lights in rooms we visited
    // Count unique rooms visited
    vector<bool> visited_room(n, false);
    current = -1;
    for (int i = 0; i < n; i++) {
        if (room_pos[i].first == tasks[0].first && room_pos[i].second == tasks[0].second) {
            current = i;
            break;
        }
    }
    visited_room[current] = true;

    for (int t = 1; t < T; t++) {
        int target_r = tasks[t].first;
        int target_c = tasks[t].second;
        int target = -1;

        for (int i = 0; i < n; i++) {
            if (room_pos[i].first == target_r && room_pos[i].second == target_c) {
                target = i;
                break;
            }
        }

        if (target == -1) continue;

        vector<int> path = get_path(current, target);
        for (int room : path) {
            visited_room[room] = true;
        }

        current = target;
    }

    // We need to turn off lights in all visited rooms
    int rooms_with_lights = 0;
    for (int i = 0; i < n; i++) {
        if (visited_room[i]) rooms_with_lights++;
    }
    total_cost += rooms_with_lights;  // Turning off lights at end

    cout << total_cost << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int R, C;
    cin >> R >> C;

    vector<string> grid(R);
    for (int i = 0; i < R; i++) cin >> grid[i];

    int Q;
    cin >> Q;
    vector<pair<int,int>> tasks(Q);
    for (int i = 0; i < Q; i++) {
        cin >> tasks[i].first >> tasks[i].second;
        tasks[i].first--; tasks[i].second--;
    }

    // BFS to find paths between consecutive tasks
    int dx[] = {0,0,1,-1}, dy[] = {1,-1,0,0};

    auto bfs = [&](pair<int,int> src, pair<int,int> dst) -> vector<pair<int,int>> {
        map<pair<int,int>, pair<int,int>> parent;
        queue<pair<int,int>> q;
        q.push(src);
        parent[src] = {-1,-1};
        while (!q.empty()) {
            auto [x,y] = q.front(); q.pop();
            if (make_pair(x,y) == dst) break;
            for (int d = 0; d < 4; d++) {
                int nx = x+dx[d], ny = y+dy[d];
                if (nx>=0&&nx<R&&ny>=0&&ny<C&&grid[nx][ny]!='#'&&!parent.count({nx,ny})) {
                    parent[{nx,ny}] = {x,y};
                    q.push({nx,ny});
                }
            }
        }
        vector<pair<int,int>> path;
        for (auto cur = dst; cur != make_pair(-1,-1); cur = parent[cur]) path.push_back(cur);
        reverse(path.begin(), path.end());
        return path;
    };

    map<pair<int,int>, int> light_on, light_off;
    int time = 0;
    pair<int,int> cur = tasks[0];
    light_on[cur] = time;

    for (int i = 1; i < Q; i++) {
        auto path = bfs(cur, tasks[i]);
        for (int j = 1; j < (int)path.size(); j++) {
            time++;
            auto room = path[j];
            if (!light_on.count(room)) light_on[room] = time;
            light_off[room] = time; // will be updated
        }
        // Turn off lights not needed anymore - simplified
        cur = tasks[i];
    }

    // All lights off at end
    long long cost = 0;
    for (auto& [room, on_time] : light_on) {
        int off_time = light_off.count(room) ? light_off[room] : time;
        cost += off_time - on_time;
    }
    cout << cost << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct Edge {
    int to;
};

int R, C, N;
vector<string> grid;
vector<pair<int,int>> tasksPos;
vector<vector<int>> id;
vector<pair<int,int>> posOf;
vector<vector<int>> g;

int dr[4] = {-1, 1, 0, 0};
int dc[4] = {0, 0, -1, 1};

vector<int> parent0, depth0, tin, tout;
int timer_dfs = 0;

void dfs_build(int u, int p) {
    tin[u] = ++timer_dfs;
    parent0[u] = p;
    for (int v : g[u]) {
        if (v == p) continue;
        depth0[v] = depth0[u] + 1;
        dfs_build(v, u);
    }
    tout[u] = timer_dfs;
}

bool is_ancestor(int u, int v) {
    return tin[u] <= tin[v] && tout[v] <= tout[u];
}

struct VirtualTreeBuilder {
    int LOG;
    vector<vector<int>> up;

    VirtualTreeBuilder(int n) {
        LOG = 1;
        while ((1 << LOG) <= n) LOG++;
        up.assign(LOG, vector<int>(n, 0));
        for (int i = 0; i < n; ++i) up[0][i] = parent0[i] == -1 ? i : parent0[i];
        for (int k = 1; k < LOG; ++k) {
            for (int i = 0; i < n; ++i) {
                up[k][i] = up[k-1][up[k-1][i]];
            }
        }
    }

    int lca(int a, int b) {
        if (is_ancestor(a, b)) return a;
        if (is_ancestor(b, a)) return b;
        int x = a;
        for (int k = LOG - 1; k >= 0; --k) {
            if (!is_ancestor(up[k][x], b)) x = up[k][x];
        }
        return parent0[x];
    }

    int dist(int a, int b) {
        int w = lca(a, b);
        return depth0[a] + depth0[b] - 2 * depth0[w];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> R >> C >> T;
    grid.resize(R);
    for (int i = 0; i < R; ++i) cin >> grid[i];

    tasksPos.resize(T + 1);
    for (int i = 1; i <= T; ++i) {
        int x, y;
        cin >> x >> y;
        --x; --y;
        tasksPos[i] = {x, y};
    }

    id.assign(R, vector<int>(C, -1));
    for (int i = 0; i < R; ++i) {
        for (int j = 0; j < C; ++j) {
            if (grid[i][j] != '#') {
                id[i][j] = N++;
                posOf.push_back({i, j});
            }
        }
    }

    g.assign(N, {});
    for (int i = 0; i < R; ++i) {
        for (int j = 0; j < C; ++j) {
            if (id[i][j] == -1) continue;
            int u = id[i][j];
            for (int k = 0; k < 4; ++k) {
                int ni = i + dr[k], nj = j + dc[k];
                if (0 <= ni && ni < R && 0 <= nj && nj < C && id[ni][nj] != -1) {
                    int v = id[ni][nj];
                    g[u].push_back(v);
                }
            }
        }
    }

    int root = 0;
    while (root < N && g[root].empty()) root++;
    if (root == N) {
        cout << 0 << "\n";
        return 0;
    }

    parent0.assign(N, -1);
    depth0.assign(N, 0);
    tin.assign(N, 0);
    tout.assign(N, 0);
    dfs_build(root, -1);

    VirtualTreeBuilder vt(N);

    vector<int> special;
    special.reserve(T + 1);
    special.push_back(root);
    for (int i = 1; i <= T; ++i) {
        auto [x, y] = tasksPos[i];
        special.push_back(id[x][y]);
    }

    sort(special.begin(), special.end(), [&](int a, int b) {
        return tin[a] < tin[b];
    });
    special.erase(unique(special.begin(), special.end()), special.end());

    vector<int> nodes = special;
    int sz = (int)special.size();
    for (int i = 0; i + 1 < sz; ++i) {
        nodes.push_back(vt.lca(special[i], special[i+1]));
    }
    sort(nodes.begin(), nodes.end(), [&](int a, int b) {
        return tin[a] < tin[b];
    });
    nodes.erase(unique(nodes.begin(), nodes.end()), nodes.end());

    unordered_map<int,int> idx;
    idx.reserve(nodes.size() * 2);
    for (int i = 0; i < (int)nodes.size(); ++i) idx[nodes[i]] = i;

    vector<vector<pair<int,int>>> vg(nodes.size());
    vector<int> st;
    for (int u : nodes) {
        while (!st.empty() && !is_ancestor(st.back(), u)) st.pop_back();
        if (!st.empty()) {
            int p = st.back();
            int w = depth0[u] - depth0[p];
            vg[idx[p]].push_back({idx[u], w});
        }
        st.push_back(u);
    }

    vector<int> need(nodes.size(), 0);
    for (int i = 1; i <= T; ++i) {
        int u = id[tasksPos[i].first][tasksPos[i].second];
        need[idx[u]] = 1;
    }
    need[idx[root]] = 1;

    ll answer = 0;

    function<int(int)> dfs = [&](int u) -> int {
        int cnt = need[u];
        for (auto [v, w] : vg[u]) {
            int sub = dfs(v);
            if (sub > 0) {
                answer += 2LL * w;
                cnt += sub;
            }
        }
        return cnt;
    };

    dfs(idx[root]);

    for (int i = 1; i < T; ++i) {
        int a = id[tasksPos[i].first][tasksPos[i].second];
        int b = id[tasksPos[i+1].first][tasksPos[i+1].second];
        answer += vt.dist(a, b);
    }
    answer += vt.dist(root, id[tasksPos[1].first][tasksPos[1].second]);

    cout << answer << "\n";
    return 0;
}

