#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 200005
#define LOG 20
#define INFLL ((long long)4e18)

typedef long long ll;

typedef struct Edge {
    int to, next;
} Edge;

static Edge edges[2 * MAXN];
static int head[MAXN], ecnt = 0;

static int parent[LOG][MAXN];
static int depth[MAXN];
static int tin[MAXN], tout[MAXN], timer2 = 0;

static int order[MAXN], qh, qt;

static int isKey[MAXN];
static int usedMark[MAXN];
static int stk[MAXN];

static int vnodes[MAXN];
static int vhead[MAXN], vecnt;
static Edge vedges[2 * MAXN];

static int degv[MAXN];
static int keyList[MAXN], keyCnt;

static ll dp0[MAXN], dp1[MAXN];

static int R, C, K;
static char grid[505][505];
static int id[505][505];
static int rr[MAXN], cc[MAXN];
static int N = 0;

static inline int min_int(int a, int b) { return a < b ? a : b; }
static inline ll min_ll(ll a, ll b) { return a < b ? a : b; }

static void add_edge(int u, int v) {
    edges[ecnt].to = v;
    edges[ecnt].next = head[u];
    head[u] = ecnt++;
}

static void add_vedge(int u, int v) {
    vedges[vecnt].to = v;
    vedges[vecnt].next = vhead[u];
    vhead[u] = vecnt++;
}

static void build_tree() {
    static int que[MAXN];
    int front = 0, back = 0;
    que[back++] = 1;
    parent[0][1] = 0;
    depth[1] = 0;

    while (front < back) {
        int u = que[front++];
        tin[u] = ++timer2;
        order[qt++] = u;
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (v == parent[0][u]) continue;
            parent[0][v] = u;
            depth[v] = depth[u] + 1;
            que[back++] = v;
        }
    }

    for (int i = qt - 1; i >= 0; --i) {
        int u = order[i];
        tout[u] = timer2;
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (v == parent[0][u]) continue;
            if (tout[v] > tout[u]) tout[u] = tout[v];
        }
    }

    for (int j = 1; j < LOG; ++j) {
        for (int i = 1; i <= N; ++i) {
            int p = parent[j - 1][i];
            parent[j][i] = p ? parent[j - 1][p] : 0;
        }
    }
}

static int is_ancestor(int u, int v) {
    return tin[u] <= tin[v] && tout[v] <= tout[u];
}

static int lca(int u, int v) {
    if (is_ancestor(u, v)) return u;
    if (is_ancestor(v, u)) return v;
    for (int j = LOG - 1; j >= 0; --j) {
        int p = parent[j][u];
        if (p && !is_ancestor(p, v)) u = p;
    }
    return parent[0][u];
}

static int cmp_tin(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    if (tin[x] < tin[y]) return -1;
    if (tin[x] > tin[y]) return 1;
    return 0;
}

static void clear_virtual(int cnt) {
    for (int i = 0; i < cnt; ++i) {
        int u = vnodes[i];
        vhead[u] = -1;
        degv[u] = 0;
        usedMark[u] = 0;
        isKey[u] = 0;
    }
    vecnt = 0;
}

static int build_virtual_tree(int *arr, int cnt) {
    if (cnt == 0) return 0;

    qsort(arr, cnt, sizeof(int), cmp_tin);

    static int tmp[MAXN];
    int m = 0;
    for (int i = 0; i < cnt; ++i) tmp[m++] = arr[i];
    for (int i = 0; i + 1 < cnt; ++i) tmp[m++] = lca(arr[i], arr[i + 1]);

    qsort(tmp, m, sizeof(int), cmp_tin);

    int uniq = 0;
    for (int i = 0; i < m; ++i) {
        if (i == 0 || tmp[i] != tmp[i - 1]) tmp[uniq++] = tmp[i];
    }

    for (int i = 0; i < uniq; ++i) {
        int u = tmp[i];
        vnodes[i] = u;
        usedMark[u] = 1;
        vhead[u] = -1;
        degv[u] = 0;
    }
    vecnt = 0;

    int top = 0;
    stk[top++] = tmp[0];
    for (int i = 1; i < uniq; ++i) {
        int u = tmp[i];
        while (top >= 2 && !is_ancestor(stk[top - 1], u)) {
            int child = stk[--top];
            int par = stk[top - 1];
            add_vedge(par, child);
            degv[par]++;
        }
        stk[top++] = u;
    }
    while (top > 1) {
        int child = stk[--top];
        int par = stk[top - 1];
        add_vedge(par, child);
        degv[par]++;
    }

    return uniq;
}

