int dy[] = {0, 0, -1, 1};

// BFS to compute distances from a source room
void bfs(int sr, int sc) {
    int qr[MAXN*MAXN], qc[MAXN*MAXN];
    int front = 0, rear = 0;
    for (int i = 0; i < R; i++)
        for (int j = 0; j < C; j++)
            dist[i][j] = -1;
    dist[sr][sc] = 0;
    qr[rear] = sr; qc[rear] = sc; rear++;
    while (front < rear) {
        int r = qr[front], c = qc[front]; front++;
        for (int d = 0; d < 4; d++) {
            int nr = r + dx[d], nc = c + dy[d];
            if (nr >= 0 && nr < R && nc >= 0 && nc < C && grid[nr][nc] == '.' && dist[nr][nc] == -1) {
                dist[nr][nc] = dist[r][c] + 1;
                qr[rear] = nr; qc[rear] = nc; rear++;
            }
        }
    }
}

