import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int R = sc.nextInt(), C = sc.nextInt();
        char[][] grid = new char[R][C];
        for (int i = 0; i < R; i++) grid[i] = sc.next().toCharArray();

        // BFS to find distances
        int[] dr = {0,0,1,-1}, dc = {1,-1,0,0};

        int T = sc.nextInt();
        int[][] tasks = new int[T][2];
        for (int i = 0; i < T; i++) {
            tasks[i][0] = sc.nextInt();
            tasks[i][1] = sc.nextInt();
        }

        // For each pair of consecutive tasks, find path length
        // Assuming start at tasks[0]
        long totalTime = 0;
        int[] cur = tasks[0];

        for (int t = 1; t < T; t++) {
            int[] next = tasks[t];
            // BFS from cur to next
            int[][] dist = new int[R][C];
            for (int[] row : dist) Arrays.fill(row, -1);
            Queue<int[]> q = new LinkedList<>();
            q.add(cur);
            dist[cur[0]][cur[1]] = 0;
            while (!q.isEmpty()) {
                int[] p = q.poll();
                for (int d = 0; d < 4; d++) {
                    int nr = p[0]+dr[d], nc = p[1]+dc[d];
                    if (nr>=0&&nr<R&&nc>=0&&nc<C&&grid[nr][nc]!='#'&&dist[nr][nc]==-1) {
                        dist[nr][nc] = dist[p[0]][p[1]] + 1;
                        q.add(new int[]{nr,nc});
                    }
                }
            }
            totalTime += dist[next[0]][next[1]];
            cur = next;
        }

        System.out.println(totalTime);
    }
}

