public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;
        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }
        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            if (c == -1) return null;
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static int N;
    static ArrayList<Integer>[] g;
    static int LOG = 20;
    static int[][] up;
    static int[] depth;
    static int[] tin, tout;
    static int timer = 0;

    static void dfs(int v, int p) {
        tin[v] = ++timer;
        up[0][v] = p;
        for (int i = 1; i < LOG; i++) up[i][v] = up[i - 1][up[i - 1][v]];
        for (int to : g[v]) {
            if (to == p) continue;
            depth[to] = depth[v] + 1;
            dfs(to, v);
        }
        tout[v] = timer;
    }

    static boolean isAncestor(int a, int b) {
        return tin[a] <= tin[b] && tout[b] <= tout[a];
    }

    static int lca(int a, int b) {
        if (isAncestor(a, b)) return a;
        if (isAncestor(b, a)) return b;
        for (int i = LOG - 1; i >= 0; i--) {
            int x = up[i][a];
            if (!isAncestor(x, b)) a = x;
        }
        return up[0][a];
    }

    static int dist(int a, int b) {
        int l = lca(a, b);
        return depth[a] + depth[b] - 2 * depth[l];
    }

    static ArrayList<Integer> getAncestorsInclusive(int x) {
        ArrayList<Integer> res = new ArrayList<>();
        while (true) {
            res.add(x);
            if (up[0][x] == x) break;
            x = up[0][x];
        }
        return res;
    }

    static void addNeed(HashMap<Integer, int[]> map, int node, int t, boolean initialOn, boolean finalOn) {
        int[] a = map.get(node);
        if (a == null) {
            a = new int[]{t, t, 0, 0}; // minT, maxT, initFlag, finalFlag
            map.put(node, a);
        } else {
            if (t < a[0]) a[0] = t;
            if (t > a[1]) a[1] = t;
        }
        if (initialOn) a[2] = 1;
        if (finalOn) a[3] = 1;
    }

    static long transitionCost(int x, int v, int y, int u) {
        HashMap<Integer, int[]> map = new HashMap<>();

        // Initially lit path v..x, needed at time 0
        int cur = x;
        while (true) {
            addNeed(map, cur, 0, true, false);
            if (cur == v) break;
            cur = up[0][cur];
        }

        // Final lit path u..y, needed at time d
        int d = dist(x, y);
        cur = y;
        while (true) {
            addNeed(map, cur, d, false, true);
            if (cur == u) break;
            cur = up[0][cur];
        }

        // Visited path x..y with visit times
        int l = lca(x, y);
        int t = 0;
        cur = x;
        while (cur != l) {
            addNeed(map, cur, t, false, false);
            cur = up[0][cur];
            t++;
        }
        addNeed(map, l, t, false, false);
        ArrayList<Integer> down = new ArrayList<>();
        cur = y;
        while (cur != l) {
            down.add(cur);
            cur = up[0][cur];
        }
        for (int i = down.size() - 1; i >= 0; i--) {
            t++;
            addNeed(map, down.get(i), t, false, false);
        }

        long sum = 0;
        for (int[] a : map.values()) {
            sum += (a[1] - a[0]);   // time on
            if (a[2] == 0) sum += 1; // switch on
            if (a[3] == 0) sum += 1; // switch off
        }
        return sum;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        String first = fs.next();
        if (first == null) return;
        int R = Integer.parseInt(first);
        int C = fs.nextInt();
        char[][] grid = new char[R][];
        for (int i = 0; i < R; i++) grid[i] = fs.next().toCharArray();

        int[][] id = new int[R][C];
        for (int i = 0; i < R; i++) Arrays.fill(id[i], -1);

        N = 0;
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                if (grid[i][j] != '#') id[i][j] = N++;
            }
        }

        g = new ArrayList[N];
        for (int i = 0; i < N; i++) g[i] = new ArrayList<>();
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                if (id[i][j] == -1) continue;
                int a = id[i][j];
                for (int k = 0; k < 4; k++) {
                    int ni = i + dr[k], nj = j + dc[k];
                    if (0 <= ni && ni < R && 0 <= nj && nj < C && id[ni][nj] != -1) {
                        int b = id[ni][nj];
                        if (a < b) {
                            g[a].add(b);
                            g[b].add(a);
                        }
                    }
                }
            }
        }

        int M = fs.nextInt();
        int[] tasks = new int[M];
        for (int i = 0; i < M; i++) {
            int r = fs.nextInt() - 1;
            int c = fs.nextInt() - 1;
            tasks[i] = id[r][c];
        }

        if (M == 0) {
            System.out.println(0);
            return;
        }

        LOG = 1;
        while ((1 << LOG) <= Math.max(1, N)) LOG++;
        up = new int[LOG][N];
        depth = new int[N];
        tin = new int[N];
        tout = new int[N];

        dfs(0, 0);

        ArrayList<Integer> anc0 = getAncestorsInclusive(tasks[0]);
        long[] dpPrev = new long[anc0.size()];
        Arrays.fill(dpPrev, Long.MAX_VALUE / 4);

        // Initially we start by entering first task room and switching its light on.
        // Only that room can be on.
        dpPrev[0] = 1; // anc0.get(0) == tasks[0]

        for (int i = 0; i + 1 < M; i++) {
            int x = tasks[i], y = tasks[i + 1];
            ArrayList<Integer> ax = getAncestorsInclusive(x);
            ArrayList<Integer> ay = getAncestorsInclusive(y);

            long[] dpNext = new long[ay.size()];
            Arrays.fill(dpNext, Long.MAX_VALUE / 4);

            for (int iv = 0; iv < ax.size(); iv++) {
                int v = ax.get(iv);
                long base = dpPrev[iv];
                if (base >= Long.MAX_VALUE / 8) continue;
                for (int iu = 0; iu < ay.size(); iu++) {
                    int u = ay.get(iu);
                    long cost = transitionCost(x, v, y, u);
                    dpNext[iu] = Math.min(dpNext[iu], base + cost);
                }
            }
            dpPrev = dpNext;
            anc0 = ay;
        }

        int last = tasks[M - 1];
        long ans = Long.MAX_VALUE / 4;
        for (int i = 0; i < anc0.size(); i++) {
            int u = anc0.get(i);
            long extra = depth[last] - depth[u] + 1; // turn off all lights on path u..last
            ans = Math.min(ans, dpPrev[i] + extra);
        }

        System.out.println(ans);
    }
}

import sys
from collections import deque, defaultdict

def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    R, C = int(input_data[idx]), int(input_data[idx+1])
    idx += 2

    grid = []
    for i in range(R):
        grid.append(input_data[idx])
        idx += 1

    # BFS to find all rooms and build adjacency
    rooms = []
    room_id = {}
    for i in range(R):
        for j in range(C):
            if grid[i][j] == '.':
                room_id[(i,j)] = len(rooms)
                rooms.append((i,j))

    adj = defaultdict(list)
    for (i,j) in rooms:
        for di,dj in [(-1,0),(1,0),(0,-1),(0,1)]:
            ni,nj = i+di, j+dj
            if 0<=ni<R and 0<=nj<C and grid[ni][nj]=='.':
                adj[room_id[(i,j)]].append(room_id[(ni,nj)])

    K = int(input_data[idx]); idx += 1
    tasks = []
    for _ in range(K):
        r,c = int(input_data[idx]), int(input_data[idx+1])
        idx += 2
        tasks.append(room_id[(r,c)])

    # BFS shortest path
    def bfs_path(src, dst):
        parent = {src: -1}
        q = deque([src])
        while q:
            u = q.popleft()
            if u == dst: break
            for v in adj[u]:
                if v not in parent:
                    parent[v] = u
                    q.append(v)
        path = []
        cur = dst
        while cur != -1:
            path.append(cur)
            cur = parent[cur]
        return path[::-1]

    print("Solution requires more problem specification")

solve()
